const chainResult = $input.first().json;

let scoringResult =
  chainResult.output ??
  chainResult.text ??
  chainResult.response ??
  chainResult;

if (
  scoringResult &&
  typeof scoringResult === 'object' &&
  scoringResult.output &&
  !scoringResult.questionScores
) {
  scoringResult = scoringResult.output;
}

if (typeof scoringResult === 'string') {
  try {
    scoringResult = JSON.parse(scoringResult);
  } catch (error) {
    throw new Error(
      `INVALID_ANSWER_SCORING_JSON: ${error.message}`
    );
  }
}

const promptContext =
  $('Build Answer Scoring Prompt').first().json;

const answerRecords =
  promptContext.answerRecords;

const explanatoryRecords = answerRecords.filter(
  (record) => record.type === 'explanatory'
);

const errors = [];

if (
  !scoringResult ||
  typeof scoringResult !== 'object' ||
  Array.isArray(scoringResult)
) {
  errors.push('scoring result must be an object');
}

const questionScores = Array.isArray(
  scoringResult?.questionScores
)
  ? scoringResult.questionScores
  : [];

const scoreById = new Map();

for (const item of questionScores) {
  const id = String(item?.id ?? '').trim();
  const score = Number(item?.score);

  if (scoreById.has(id)) {
    errors.push(`duplicate score for ${id}`);
    continue;
  }

  if (!Number.isInteger(score) || score < 0 || score > 4) {
    errors.push(
      `${id || 'unknown'}: score must be an integer from 0 to 4`
    );
    continue;
  }

  if (
    typeof item?.rationale !== 'string' ||
    !item.rationale.trim()
  ) {
    errors.push(`${id}: rationale is required`);
    continue;
  }

  scoreById.set(id, {
    score,
    rationale: String(item.rationale).trim(),
  });
}

const mergedRecords = answerRecords.map(
  (record) => {
    if (record.type !== 'explanatory') {
      return { ...record };
    }

    const scored = scoreById.get(record.id);

    if (!scored) {
      return { ...record };
    }

    return {
      ...record,
      llmScore: scored.score,
      llmRationale: scored.rationale,
      finalScore: scored.score,
    };
  }
);

const scoredExplanatoryCount = mergedRecords.filter(
  (record) => record.type === 'explanatory' &&
  Number.isInteger(record.finalScore)
).length;

if (scoredExplanatoryCount !== explanatoryRecords.length) {
  errors.push('not every explanatory answer received a valid score');
}

if (!Array.isArray(scoringResult?.warnings)) {
  errors.push('warnings must be an array');
}

if (
  typeof scoringResult?.interviewSummary !== 'string' ||
  !scoringResult.interviewSummary.trim()
) {
  errors.push('interviewSummary is required');
}

if (errors.length > 0) {
  throw new Error(`INVALID_ANSWER_SCORES: ${errors.join("; ")}`);
}

const warnings = scoringResult.warnings.map(String).slice(0, 20);

if (scoreById.size > explanatoryRecords.length) {
  warnings.push('The model returned scores for unknown question ids; they were ignored.');
}

return [
  {
    json: {
      interviewContext: promptContext.interviewContext,
      answerRecords: mergedRecords,
      answerScoring: {
        schemaVersion: '1.0',
        interviewSummary: String(
          scoringResult.interviewSummary
        ).trim(),
        warnings,
      },
    },
  },
];

const validated = $input.first().json;

const interviewContext =
  validated.interviewContext;

const answerRecords =
  validated.answerRecords;

const gradeGuide =
  interviewContext.gradeGuide;

const dimensions =
  gradeGuide.dimensions;

const grades = Array.isArray(gradeGuide.grades)
  ? gradeGuide.grades
  : [];

const resumeDimensionByCode = new Map(
  interviewContext.resumeGrade.dimensions.map(
    (dimension) => [dimension.code, dimension]
  )
);

const dimensionScores = [];

for (const dimension of dimensions) {
  const dimensionRecords = answerRecords.filter(
    (record) => record.dimensionCode === dimension.code
  );

  const questionScores = dimensionRecords.map(
    (record) => Number(record.finalScore)
  );

  if (questionScores.length === 0) {
    throw new Error(
      `NO_INTERVIEW_QUESTIONS_FOR_DIMENSION: ${dimension.code}`
    );
  }

  const average =
    questionScores.reduce(
      (total, score) => total + score,
      0
    ) / questionScores.length;

  const interviewScore =
    Math.round(average * 100) / 100;

  const resumeDimension =
    resumeDimensionByCode.get(dimension.code);

  const roundQuestionCounts = { first: 0, followUp: 0 };

  for (const record of dimensionRecords) {
    roundQuestionCounts[record.round] += 1;
  }

  dimensionScores.push({
    code: dimension.code,
    title: dimension.title,
    weight: Number(dimension.weight),
    questionCount: questionScores.length,
    roundQuestionCounts,
    interviewScore,
    resumeScore:
      resumeDimension === undefined
        ? null
        : Number(resumeDimension.effectiveScore),
    delta:
      resumeDimension === undefined
        ? null
        : Math.round(
            (interviewScore -
              Number(resumeDimension.effectiveScore)) *
            100
          ) / 100,
  });
}

const overallScore =
  Math.round(
    dimensionScores.reduce(
      (total, dimension) =>
        total + (dimension.interviewScore / 4) * dimension.weight,
      0
    ) * 100
  ) / 100;

const gradeChecks = [];

for (const grade of grades) {
  const minimumLevels =
    grade.minimumDimensionLevels ?? {};

  const dimensionChecks = Object.entries(minimumLevels).map(
    ([code, minimumRequired]) => {
      const dimension = dimensionScores.find(
        (item) => item.code === code
      );

      if (!dimension) {
        throw new Error(
          `GRADE_DIMENSION_NOT_FOUND: ${code}`
        );
      }

      return {
        code,
        minimumRequired: Number(minimumRequired),
        interviewScore: dimension.interviewScore,
        met:
          dimension.interviewScore >=
          Number(minimumRequired),
      };
    }
  );

  const overallMet =
    overallScore >= Number(grade.minimumOverallScore);

  gradeChecks.push({
    code: grade.code,
    label: grade.label,
    minimumOverallScore: Number(grade.minimumOverallScore),
    overallMet,
    dimensionChecks,
    met:
      overallMet &&
      dimensionChecks.every((check) => check.met),
  });
}

const metGrades = gradeChecks.filter(
  (check) => check.met
);

const assigned =
  metGrades.length > 0
    ? metGrades.reduce(
        (best, check) =>
          Number(check.minimumOverallScore) >=
          Number(best.minimumOverallScore)
            ? check
            : best
      )
    : null;

const assignedGrade = assigned
  ? {
      code: assigned.code,
      label: assigned.label,
      minimumOverallScore: assigned.minimumOverallScore,
      basis: 'INTERVIEW_ANSWERS',
    }
  : {
      code: 'NO_MATCH',
      label: 'کمتر از حداقل همه گریدها',
